query:
-- Clientes de teste
SELECT 'allowed_clients' as tabela, id, name as identificador FROM allowed_clients 
WHERE LOWER(name) LIKE '%teste%' OR LOWER(name) LIKE '%test%' OR LOWER(email) LIKE '%teste%' OR LOWER(email) LIKE '%test%';

-- Usuários de teste
SELECT 'users' as tabela, id, name as identificador FROM users 
WHERE LOWER(name) LIKE '%teste%' OR LOWER(name) LIKE '%test%' OR LOWER(email) LIKE '%teste%' OR LOWER(email) LIKE '%test%';

-- Funcionários de teste
SELECT 'employees' as tabela, id, name as identificador FROM employees 
WHERE LOWER(name) LIKE '%teste%' OR LOWER(name) LIKE '%test%';

-- Cobranças de teste
SELECT 'subscription_charges' as tabela, id, description as identificador FROM subscription_charges 
WHERE LOWER(description) LIKE '%teste%' OR LOWER(description) LIKE '%test%';

